def candle_shadow_ratios(o, h, l, c):
    if h == l:
        return (0.0, 0.0)
    rng = h - l
    upper = (h - max(o, c)) / rng
    lower = (min(o, c) - l) / rng
    return (upper, lower)

candle_shadow_ratios(100.0, 110.0, 90.0, 105.0)

def generate_dollar_bars(ticks, threshold_dollar=100000.0):
    bars_close = []
    cum_dollar = 0.0
    for p, v in ticks:
        cum_dollar += p * v
        if cum_dollar >= threshold_dollar:
            bars_close.append(p)
            cum_dollar = 0.0
    return bars_close

generate_dollar_bars([(10.0, 5000), (10.2, 6000), (10.5, 10000)], 100000.0)

def calculate_net_pnl(buy_val, sell_val, comm_rate=0.0002, tax_rate=0.0005, slippage=0.0005):
    gross = sell_val - buy_val
    buy_cost = buy_val * (comm_rate + slippage)
    sell_cost = sell_val * (comm_rate + tax_rate + slippage)
    return gross - (buy_cost + sell_cost)

calculate_net_pnl(100000.0, 110000.0)

def hedge_ratio(stock_beta, stock_value, future_beta=1.0):
    return (stock_beta * stock_value) / future_beta

hedge_ratio(1.1, 5000.0)
